"use strict";
import { QueryClient } from "@tanstack/react-query";
import { injectedWithFallback } from "components/Web3Provider/injectedWithFallback";
import { WC_PARAMS } from "components/Web3Provider/walletConnect";
import { getChainInfo } from "uniswap/src/features/chains/chainInfo";
import { ALL_CHAIN_IDS } from "uniswap/src/features/chains/types";
import { isTestnetChain } from "uniswap/src/features/chains/utils";
import { isPlaywrightEnv } from "utilities/src/environment/env";
import { logger } from "utilities/src/logger/logger";
import { createClient } from "viem";
import { createConfig, fallback, http } from "wagmi";
import { connect } from "wagmi/actions";
import { injected, metaMask, mock, walletConnect } from "wagmi/connectors";
export const orderedTransportUrls = (chain) => {
  const orderedRpcUrls = [
    ...chain.rpcUrls.interface?.http ?? [],
    ...chain.rpcUrls.default?.http ?? [],
    ...chain.rpcUrls.public?.http ?? [],
    ...chain.rpcUrls.fallback?.http ?? []
  ];
  return Array.from(new Set(orderedRpcUrls.filter(Boolean)));
};
const baseConnectors = [
  injectedWithFallback(),
  walletConnect(WC_PARAMS),
  metaMask()
];
const connectors = isPlaywrightEnv() ? [
  ...baseConnectors,
  mock({
    features: {},
    accounts: ["0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266"]
  })
] : baseConnectors;
export const wagmiConfig = createConfig({
  chains: ALL_CHAIN_IDS.map(getChainInfo),
  connectors,
  client({ chain }) {
    return createClient({
      chain,
      batch: { multicall: true },
      pollingInterval: 12e3,
      transport: fallback(
        orderedTransportUrls(chain).map(
          (url) => http(url, { onFetchResponse: (response) => onFetchResponse(response, chain, url) })
        )
      )
    });
  }
});
const onFetchResponse = (response, chain, url) => {
  if (response.status !== 200) {
    const message = `RPC provider returned non-200 status: ${response.status}`;
    if (isTestnetChain(chain.id)) {
      logger.warn("wagmiConfig.ts", "client", message, {
        extra: {
          chainId: chain.id,
          url
        }
      });
    } else {
      logger.error(new Error(message), {
        extra: {
          chainId: chain.id,
          url
        },
        tags: {
          file: "wagmiConfig.ts",
          function: "client"
        }
      });
    }
  }
};
export const queryClient = new QueryClient();
if (window.Cypress?.eagerlyConnect) {
  connect(wagmiConfig, { connector: injected() });
}
const isEagerlyConnect = !window.location.search.includes("eagerlyConnect=false");
if (isPlaywrightEnv() && isEagerlyConnect) {
  setTimeout(() => {
    connect(wagmiConfig, {
      connector: mock({
        features: {},
        accounts: ["0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266"]
      })
    });
  }, 1);
}
