import { useMemo, useRef } from 'react'
import { ethers, BigNumber } from 'ethers'
import { AccountMeta } from 'uniswap/src/features/accounts/types'
import { useTransactionGasFee } from 'uniswap/src/features/gas/hooks'
import { isAbstractChain } from 'uniswap/src/constants/abstractContracts'
import { useWrapTransactionRequest } from 'uniswap/src/features/transactions/swap/contexts/hooks/useWrapTransactionRequest'
import { WRAP_FALLBACK_GAS_LIMIT_IN_GWEI } from 'uniswap/src/features/transactions/swap/review/services/swapTxAndGasInfoService/constants'
import {
  TransactionRequestInfo,
  getIsWrapApplicable,
  processWrapResponse,
} from 'uniswap/src/features/transactions/swap/review/services/swapTxAndGasInfoService/utils'
import { DerivedSwapInfo } from 'uniswap/src/features/transactions/swap/types/derivedSwapInfo'
import { TokenApprovalInfo } from 'uniswap/src/features/transactions/swap/types/trade'
import { getAbstractContracts } from 'uniswap/src/constants/abstractContracts'
import { CurrencyField } from 'uniswap/src/types/currency'
import { getTradeSettingsDeadline } from 'uniswap/src/data/apiClients/tradingApi/utils/getTradeSettingsDeadline'
import { useTransactionSettingsContext } from 'uniswap/src/features/transactions/settings/contexts/TransactionSettingsContext'

export function useWrapTransactionRequestInfo({
  derivedSwapInfo,
  account,
}: {
  derivedSwapInfo: DerivedSwapInfo
  account?: AccountMeta
}): TransactionRequestInfo {
  const wrapTxRequest = useWrapTransactionRequest(derivedSwapInfo, account)
  const gasFeeResult = useTransactionGasFee(
    wrapTxRequest,
    !getIsWrapApplicable({ derivedSwapInfo }),
    undefined,
    WRAP_FALLBACK_GAS_LIMIT_IN_GWEI * 10e9,
  ) // Skip Gas Fee API call on transactions that don't need wrapping

  const result = useMemo(() => processWrapResponse({ gasFeeResult, wrapTxRequest }), [gasFeeResult, wrapTxRequest])

  const cachedGasFeeResultRef = useRef(gasFeeResult)
  if (gasFeeResult.value) {
    cachedGasFeeResultRef.current = gasFeeResult
  }

  // Wrap gas cost should not change significantly between trades, so we can use the last value if current is unavailable.
  const resultWithCaching = useMemo(() => {
    const value = result.gasFeeResult.value ?? cachedGasFeeResultRef.current.value
    const displayValue = result.gasFeeResult.displayValue ?? cachedGasFeeResultRef.current.displayValue

    const gasFeeResultWithCaching = {
      ...result.gasFeeResult,
      value,
      displayValue,
    }

    return { ...result, gasFeeResult: gasFeeResultWithCaching }
  }, [result])

  return resultWithCaching
}

// Abstract DEX transaction request info hook
function useAbstractTransactionRequestInfo({
  derivedSwapInfo,
  account,
}: {
  derivedSwapInfo: DerivedSwapInfo
  account?: AccountMeta
}): TransactionRequestInfo {

  const { trade, chainId, currencyAmounts } = derivedSwapInfo
  const abstractContracts = getAbstractContracts(chainId)
  
  // Get user's transaction settings
  const { customDeadline } = useTransactionSettingsContext()

  // Create mock transaction request for Abstract DEX swaps
  const mockTxRequest = useMemo(() => {
    if (!trade.trade || !account?.address || !abstractContracts?.router) {
      return undefined
    }

    const inputAmount = currencyAmounts[CurrencyField.INPUT]
    const outputAmount = currencyAmounts[CurrencyField.OUTPUT]

    if (!inputAmount || !outputAmount) {
      return undefined
    }

    // Get original currencies before any wrapping for native token detection
    const originalInputCurrency = inputAmount.currency
    const originalOutputCurrency = outputAmount.currency

    // Generate proper V2 swap calldata
    const isExactInput = trade.trade.tradeType === 0 // TradeType.EXACT_INPUT = 0
    
    // Get user's deadline setting or fallback to 30 minutes (default)
    const deadline = getTradeSettingsDeadline(customDeadline) || (Math.floor(Date.now() / 1000) + 1800) // 30 minutes = 1800 seconds
    
    // Get user's slippage tolerance from trade object, fallback to 0.5%
    // We use slippageTolerancePercent which is the Percent object for calculations
    const userSlippagePercent = (trade.trade as any).slippageTolerancePercent
    const slippageTolerance = userSlippagePercent 
      ? Math.floor(parseFloat(userSlippagePercent.toFixed()) * 100) // Convert from decimal to basis points
      : 50 // Fallback to 0.5% (50 basis points)


    // Determine if this is a V2 or V3 trade
    // Check for standard SDK routes first
    const hasV2Routes = trade.trade.v2Routes && trade.trade.v2Routes.length > 0
    const hasV3Routes = trade.trade.v3Routes && trade.trade.v3Routes.length > 0
    
    // Check for our custom V3 trade objects
    const isCustomV3Trade = (trade.trade as any).isV3 === true
    
    const isV2Trade = hasV2Routes && !isCustomV3Trade
    const isV3Trade = hasV3Routes || isCustomV3Trade

    if (!isV2Trade && !isV3Trade) {
      throw new Error('No valid V2 or V3 route found in trade')
    }

    // Extract path from ClassicTrade -> V2Routes or V3Routes
    let path: string[] = []
    if (isV2Trade) {
      const v2Route = trade.trade.v2Routes[0]
      if (v2Route.routev2?.path) {
        path = v2Route.routev2.path.map(token => token.address)
      } else {
        throw new Error('No valid V2 route path found')
      }
    } else if (isV3Trade) {
      if (isCustomV3Trade) {
        // Our custom V3 trade objects have v3Quote with tokenIn/tokenOut
        const v3Quote = (trade.trade as any).v3Quote
        if (v3Quote?.tokenIn && v3Quote?.tokenOut) {
          path = [v3Quote.tokenIn.address, v3Quote.tokenOut.address]
          console.log('  → Extracted V3 path from custom trade:', path)
        } else {
          throw new Error('No valid V3 quote data found in custom trade')
        }
      } else {
        // Standard SDK V3 routes
        const v3Route = trade.trade.v3Routes[0]
        if (v3Route.routev3?.tokenPath) {
          path = v3Route.routev3.tokenPath.map(token => token.address)
        } else {
          throw new Error('No valid V3 route path found')
        }
      }
    }

    if (path.length < 2) {
      return undefined
    }

    let calldata: string
    let value = '0'
    let targetRouter: string

    if (isExactInput) {
      const amountIn = inputAmount.quotient.toString()

      // Get output amount - use the raw amount from our trade and apply slippage using BigNumber
      const outputAmountRaw = currencyAmounts[CurrencyField.OUTPUT]?.quotient?.toString() ||
                              inputAmount.quotient.toString() // fallback to input if output not available

      // Apply slippage tolerance using BigNumber to avoid precision issues
      const amountOutMin = BigNumber.from(outputAmountRaw)
        .mul(10000 - slippageTolerance)
        .div(10000)
        .toString()


      // Use different router based on trade type
      if (isV2Trade) {
        targetRouter = abstractContracts.router  // V2 router
      } else {
        targetRouter = abstractContracts.swapRouter  // V3 router
      }

      if (isV2Trade) {
        // V2 Trade logic
        if (originalInputCurrency.isNative && !originalOutputCurrency.isNative) {
          // ETH -> Token: Abstract DEX uses the same route format for ETH swaps
          // swapExactETHForTokens(uint amountOutMin, Route[] routes, address to, uint deadline)
          const iface = new ethers.utils.Interface([
            'function swapExactETHForTokens(uint256 amountOutMin, tuple(address from, address to, bool stable, address factory)[] routes, address to, uint256 deadline)'
          ])

          // Create routes array - each hop needs a route with factory address
          const routes = []
          for (let i = 0; i < path.length - 1; i++) {
            routes.push({
              from: path[i],
              to: path[i + 1],
              stable: false, // Use volatile pools for most tokens
              factory: abstractContracts.poolFactory // Factory address is required!
            })
          }

          calldata = iface.encodeFunctionData('swapExactETHForTokens', [
            amountOutMin, routes, account.address, deadline
          ])
          value = amountIn
        } else if (!originalInputCurrency.isNative && originalOutputCurrency.isNative) {
          // Token -> ETH: Abstract DEX uses the same route format for ETH swaps
          // swapExactTokensForETH(uint amountIn, uint amountOutMin, Route[] routes, address to, uint deadline)
          const iface = new ethers.utils.Interface([
            'function swapExactTokensForETH(uint256 amountIn, uint256 amountOutMin, tuple(address from, address to, bool stable, address factory)[] routes, address to, uint256 deadline)'
          ])

          // Create routes array - each hop needs a route with factory address
          const routes = []
          for (let i = 0; i < path.length - 1; i++) {
            routes.push({
              from: path[i],
              to: path[i + 1],
              stable: false, // Use volatile pools for most tokens
              factory: abstractContracts.poolFactory // Factory address is required!
            })
          }

          calldata = iface.encodeFunctionData('swapExactTokensForETH', [
            amountIn, amountOutMin, routes, account.address, deadline
          ])
          value = '0'
        } else {
          // Token -> Token: Abstract DEX uses Route struct format
          // swapExactTokensForTokens(uint256 amountIn, uint256 amountOutMin, Route[] routes, address to, uint256 deadline)
          const iface = new ethers.utils.Interface([
            'function swapExactTokensForTokens(uint256 amountIn, uint256 amountOutMin, tuple(address from, address to, bool stable, address factory)[] routes, address to, uint256 deadline)'
          ])

          // Create routes array - each hop needs a route with factory address
          const routes = []
          for (let i = 0; i < path.length - 1; i++) {
            routes.push({
              from: path[i],
              to: path[i + 1],
              stable: false, // Use volatile pools for most tokens
              factory: abstractContracts.poolFactory // Factory address is required!
            })
          }

          calldata = iface.encodeFunctionData('swapExactTokensForTokens', [
            amountIn, amountOutMin, routes, account.address, deadline
          ])
          value = '0'
          
        }
      } else if (isV3Trade) {
        // V3 swaps use different function signatures
        if (originalInputCurrency.isNative && !originalOutputCurrency.isNative) {
          // ETH -> Token: exactInputSingle for single hop, exactInput for multi-hop
          if (path.length === 2) {
            const iface = new ethers.utils.Interface([
              'function exactInputSingle((address tokenIn, address tokenOut, int24 tickSpacing, address recipient, uint256 deadline, uint256 amountIn, uint256 amountOutMinimum, uint160 sqrtPriceLimitX96)) external payable returns (uint256 amountOut)'
            ])
            
            // Get tickSpacing from V3 route or custom V3 trade
            let tickSpacing = 200 // Default to 200 (0.3% fee equivalent)
            if (isCustomV3Trade) {
              const v3Quote = (trade.trade as any).v3Quote
              tickSpacing = v3Quote?.tickSpacing || 200
            } else {
              const v3Route = trade.trade.v3Routes[0]
              tickSpacing = v3Route.routev3?.pools?.[0]?.tickSpacing || 200
            }
            
            calldata = iface.encodeFunctionData('exactInputSingle', [{
              tokenIn: path[0],
              tokenOut: path[1],
              tickSpacing,
              recipient: account.address,
              deadline,
              amountIn,
              amountOutMinimum: amountOutMin,
              sqrtPriceLimitX96: 0
            }])
            value = amountIn
          } else {
            // Multi-hop V3 swap
            const iface = new ethers.utils.Interface([
              'function exactInput((bytes path, address recipient, uint256 deadline, uint256 amountIn, uint256 amountOutMinimum)) external payable returns (uint256 amountOut)'
            ])
            
            // Encode path with fees (complex encoding needed for V3)
            const encodedPath = path[0] + '000bb8' + path[1] // Simple 2-hop with 0.3% fee
            
            calldata = iface.encodeFunctionData('exactInput', [{
              path: encodedPath,
              recipient: account.address,
              deadline,
              amountIn,
              amountOutMinimum: amountOutMin
            }])
            value = amountIn
          }
        } else if (!originalInputCurrency.isNative && originalOutputCurrency.isNative) {
          // Token -> ETH: Similar to above but unwrap WETH
          if (path.length === 2) {
            const iface = new ethers.utils.Interface([
              'function exactInputSingle((address tokenIn, address tokenOut, int24 tickSpacing, address recipient, uint256 deadline, uint256 amountIn, uint256 amountOutMinimum, uint160 sqrtPriceLimitX96)) external returns (uint256 amountOut)'
            ])
            
            let tickSpacing = 200 // Default to 200 (0.3% fee equivalent)
            if (isCustomV3Trade) {
              const v3Quote = (trade.trade as any).v3Quote
              tickSpacing = v3Quote?.tickSpacing || 200
            } else {
              const v3Route = trade.trade.v3Routes[0]
              tickSpacing = v3Route.routev3?.pools?.[0]?.tickSpacing || 200
            }
            
            calldata = iface.encodeFunctionData('exactInputSingle', [{
              tokenIn: path[0],
              tokenOut: path[1],
              tickSpacing,
              recipient: account.address,
              deadline,
              amountIn,
              amountOutMinimum: amountOutMin,
              sqrtPriceLimitX96: 0
            }])
            value = '0'
          } else {
            const iface = new ethers.utils.Interface([
              'function exactInput((bytes path, address recipient, uint256 deadline, uint256 amountIn, uint256 amountOutMinimum)) external returns (uint256 amountOut)'
            ])
            
            const encodedPath = path[0] + '000bb8' + path[1]
            
            calldata = iface.encodeFunctionData('exactInput', [{
              path: encodedPath,
              recipient: account.address,
              deadline,
              amountIn,
              amountOutMinimum: amountOutMin
            }])
            value = '0'
          }
        } else {
          // Token -> Token V3 swap - CRITICAL: Abstract DEX uses tickSpacing not fee!
          if (path.length === 2) {
            const iface = new ethers.utils.Interface([
              'function exactInputSingle((address tokenIn, address tokenOut, int24 tickSpacing, address recipient, uint256 deadline, uint256 amountIn, uint256 amountOutMinimum, uint160 sqrtPriceLimitX96)) external returns (uint256 amountOut)'
            ])
            
            let tickSpacing = 200 // Default to 200 (0.3% fee equivalent)
            if (isCustomV3Trade) {
              const v3Quote = (trade.trade as any).v3Quote
              tickSpacing = v3Quote?.tickSpacing || 200
            } else {
              const v3Route = trade.trade.v3Routes[0]
              tickSpacing = v3Route.routev3?.pools?.[0]?.tickSpacing || 200
            }
            
            calldata = iface.encodeFunctionData('exactInputSingle', [{
              tokenIn: path[0],
              tokenOut: path[1],
              tickSpacing,
              recipient: account.address,
              deadline,
              amountIn,
              amountOutMinimum: amountOutMin,
              sqrtPriceLimitX96: 0
            }])
            value = '0'
          } else {
            const iface = new ethers.utils.Interface([
              'function exactInput((bytes path, address recipient, uint256 deadline, uint256 amountIn, uint256 amountOutMinimum)) external returns (uint256 amountOut)'
            ])
            
            const encodedPath = path[0] + '000bb8' + path[1]
            
            calldata = iface.encodeFunctionData('exactInput', [{
              path: encodedPath,
              recipient: account.address,
              deadline,
              amountIn,
              amountOutMinimum: amountOutMin
            }])
            value = '0'
          }
        }
      }
    } else {
      // Exact output swaps - Abstract DEX doesn't support exact output functions
      // Fallback to using exact input with adjusted amounts for approximate behavior
      console.warn('Exact output swaps not supported by Abstract DEX, falling back to exact input')

      // For exact output, we'll use the input amount with extra slippage tolerance
      // This is an approximation and may not give exact output amounts
      const approximateAmountIn = currencyAmounts[CurrencyField.INPUT]?.quotient?.toString() || '0'
      const approximateAmountOutMin = BigNumber.from(outputAmount.quotient.toString())
        .mul(9500) // 95% of desired output (5% slippage buffer)
        .div(10000)
        .toString()

      if (originalInputCurrency.isNative && !originalOutputCurrency.isNative) {
        // ETH -> Token: fallback to swapExactETHForTokens
        const iface = new ethers.utils.Interface([
          'function swapExactETHForTokens(uint256 amountOutMin, tuple(address from, address to, bool stable, address factory)[] routes, address to, uint256 deadline)'
        ])

        const routes = []
        for (let i = 0; i < path.length - 1; i++) {
          routes.push({
            from: path[i],
            to: path[i + 1],
            stable: false,
            factory: abstractContracts.poolFactory
          })
        }

        calldata = iface.encodeFunctionData('swapExactETHForTokens', [
          approximateAmountOutMin, routes, account.address, deadline
        ])
        value = approximateAmountIn
      } else if (!originalInputCurrency.isNative && originalOutputCurrency.isNative) {
        // Token -> ETH: fallback to swapExactTokensForETH
        const iface = new ethers.utils.Interface([
          'function swapExactTokensForETH(uint256 amountIn, uint256 amountOutMin, tuple(address from, address to, bool stable, address factory)[] routes, address to, uint256 deadline)'
        ])

        const routes = []
        for (let i = 0; i < path.length - 1; i++) {
          routes.push({
            from: path[i],
            to: path[i + 1],
            stable: false,
            factory: abstractContracts.poolFactory
          })
        }

        calldata = iface.encodeFunctionData('swapExactTokensForETH', [
          approximateAmountIn, approximateAmountOutMin, routes, account.address, deadline
        ])
        value = '0'
      } else {
        // Token -> Token: fallback to exact input
        const iface = new ethers.utils.Interface([
          'function swapExactTokensForTokens(uint256 amountIn, uint256 amountOutMin, tuple(address from, address to, bool stable, address factory)[] routes, address to, uint256 deadline)'
        ])

        const routes = []
        for (let i = 0; i < path.length - 1; i++) {
          routes.push({
            from: path[i],
            to: path[i + 1],
            stable: false,
            factory: abstractContracts.poolFactory
          })
        }

        calldata = iface.encodeFunctionData('swapExactTokensForTokens', [
          approximateAmountIn, approximateAmountOutMin, routes, account.address, deadline
        ])
        value = '0'
      }
    }

    // Create the actual swap transaction structure
    const txRequest = {
      to: targetRouter,  // Use the correct router (V2 or V3)
      data: calldata,
      value,
      from: account.address,
      chainId: chainId, // Required for validateTransactionRequest
    }


    return txRequest
  }, [trade.trade, account?.address, abstractContracts?.router, abstractContracts?.swapRouter, currencyAmounts, customDeadline])

  // Use Abstract DEX gas estimation instead of Uniswap API
  const gasFeeResult = useMemo(() => {
    if (!mockTxRequest || !isAbstractChain(chainId)) {
      return {
        value: undefined,
        displayValue: undefined,
        error: null,
        isLoading: false,
        gasEstimates: undefined,
      }
    }

    // Hardcoded gas estimation for Abstract DEX - 1 gwei
    const gasLimitEstimate = 200000 // Gas units for V2 swap
    const gasPrice = 1000000000 // 1 gwei in wei (hardcoded)
    const gasFeeWei = (gasLimitEstimate * gasPrice).toString()
    const gasFeeUSD = 0.2 // Hardcoded to $0.20 USD

    return {
      value: gasFeeWei,
      displayValue: gasFeeWei,
      error: null,
      isLoading: false,
      gasEstimates: {
        activeEstimate: {
          strategy: 'standard' as const,
          gasLimit: gasLimitEstimate.toString(),
          gasFee: gasFeeWei,
          gasCostUSD: gasFeeUSD.toString(),
        },
        shadowEstimates: [],
      },
    }
  }, [mockTxRequest, chainId])

  return useMemo(() => {
    const gasEstimate = {
      swapEstimates: gasFeeResult.gasEstimates || [{
        strategy: 'standard' as const,
        gasLimit: '200000',
        gasCostUSD: '0.20',
      }],
    }

    return {
      gasFeeResult,
      txRequests: mockTxRequest ? [mockTxRequest] : undefined,
      gasEstimate,
      swapRequestArgs: undefined,
    }
  }, [gasFeeResult, mockTxRequest])
}

export function useTransactionRequestInfo({
  derivedSwapInfo,
  tokenApprovalInfo,
  account,
}: {
  derivedSwapInfo: DerivedSwapInfo
  tokenApprovalInfo: TokenApprovalInfo | undefined
  account?: AccountMeta
}): TransactionRequestInfo {
  const wrapTransactionRequestInfo = useWrapTransactionRequestInfo({
    derivedSwapInfo,
    account,
  })

  const abstractTransactionRequestInfo = useAbstractTransactionRequestInfo({
    derivedSwapInfo,
    account
  })

  const isWrapApplicable = getIsWrapApplicable({ derivedSwapInfo })


  // Handle wrapping (ETH <-> WETH)
  if (isWrapApplicable) {
    return wrapTransactionRequestInfo
  }

  // All other trades go through Abstract DEX
  return abstractTransactionRequestInfo
}
